import { test, expect } from '@playwright/test';

test.describe('Notification Badge Count', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-application-url.com');
  });

  test('should display notification bell icon', async ({ page }) => {
    const bellIcon = page.getByRole('img', { name: /notification bell/i });
    await expect(bellIcon).toBeVisible();
  });

  test('should display correct badge count on notification bell icon', async ({ page }) => {
    const bellIcon = page.getByRole('img', { name: /notification bell/i });
    const badgeCount = bellIcon.locator('.badge-count'); // Assuming badge count has a class 'badge-count'

    await expect(badgeCount).toBeVisible();
    await expect(badgeCount).toHaveText('3'); // Replace '3' with the expected count
  });
});
